function check([req_skills, people], actual, expected) {
  if (!Array.isArray(actual) || !Array.isArray(expected) || actual.length !== expected.length) return false;
  const chosen = new Set();
  const covered = new Set();
  for (const index of actual) {
    if (!Number.isInteger(index) || index < 0 || index >= people.length || chosen.has(index)) return false;
    chosen.add(index);
    for (const skill of people[index]) covered.add(skill);
  }
  return req_skills.every(skill => covered.has(skill));
}

