function validate([req_skills, people]) {
  const word = s => typeof s === 'string' && /^[a-z]{1,16}$/.test(s);
  if (!Array.isArray(req_skills) || req_skills.length < 1 || req_skills.length > 16) return 'req_skills needs 1 to 16 skills.';
  if (!req_skills.every(word)) return 'Each skill is 1 to 16 lowercase letters.';
  const required = new Set(req_skills);
  if (required.size !== req_skills.length) return 'The skills in req_skills must be distinct.';
  if (!Array.isArray(people) || people.length < 1 || people.length > 60) return 'people needs 1 to 60 people.';
  const covered = new Set();
  for (const skills of people) {
    if (!Array.isArray(skills) || skills.length > 16) return 'Each person has at most 16 skills.';
    if (!skills.every(word)) return 'Each skill is 1 to 16 lowercase letters.';
    if (new Set(skills).size !== skills.length) return "A person's skills must be distinct.";
    if (!skills.every(skill => required.has(skill))) return 'Every skill a person has must appear in req_skills.';
    for (const skill of skills) covered.add(skill);
  }
  if (covered.size !== required.size) return 'Some required skill is held by nobody, so no sufficient team exists.';
  return null;
}

