function smallestSufficientTeam(req_skills, people) {
  const skillIndex = new Map(req_skills.map((skill, i) => [skill, i]));
  const full = (1 << req_skills.length) - 1;
  const masks = people.map(skills => skills.reduce((mask, skill) => mask | (1 << skillIndex.get(skill)), 0));
  const size = new Array(full + 1).fill(Infinity);
  const lastPerson = new Array(full + 1).fill(-1);
  const previous = new Array(full + 1).fill(-1);
  size[0] = 0;
  for (let mask = 0; mask <= full; mask++) {
    if (size[mask] === Infinity) continue;
    for (let person = 0; person < people.length; person++) {
      const next = mask | masks[person];
      if (size[mask] + 1 < size[next]) {
        size[next] = size[mask] + 1;
        lastPerson[next] = person;
        previous[next] = mask;
      }
    }
  }
  const team = [];
  for (let mask = full; mask !== 0; mask = previous[mask]) {
    team.push(lastPerson[mask]);
  }
  return team;
}

