function smallestSufficientTeam(req_skills, people) {
  // Try every subset of people and keep the smallest one that covers all skills.
  let best = null;
  for (let subset = 0; subset < 2 ** people.length; subset++) {
    const members = [];
    for (let i = 0; i < people.length; i++) if (Math.floor(subset / 2 ** i) % 2 === 1) members.push(i);
    if (best !== null && members.length >= best.length) continue;
    const have = new Set(members.flatMap(i => people[i]));
    if (req_skills.every(skill => have.has(skill))) best = members;
  }
  return best;
}

