function generate(rand, size) {
  const large = size === 'large';
  const skillCount = large ? 16 : 1 + Math.floor(rand() * 5);
  const peopleCount = large ? 60 : 1 + Math.floor(rand() * 7);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const names = new Set();
  while (names.size < skillCount) {
    const length = 1 + Math.floor(rand() * (large ? 16 : 4));
    let name = '';
    for (let i = 0; i < length; i++) name += letters[Math.floor(rand() * 26)];
    names.add(name);
  }
  const req_skills = [...names];
  const most = large ? 5 : skillCount;
  const people = Array.from({ length: peopleCount }, () => {
    const count = Math.floor(rand() * (most + 1));
    const skills = new Set();
    for (let i = 0; i < count; i++) skills.add(req_skills[Math.floor(rand() * skillCount)]);
    return [...skills];
  });
  // Guarantee a sufficient team: hand each uncovered skill to a random person.
  const covered = new Set(people.flat());
  for (const skill of req_skills) {
    if (!covered.has(skill)) people[Math.floor(rand() * peopleCount)].push(skill);
  }
  return [req_skills, people];
}
